/// <summary>
/// The <c>AVAPriceIncreaseController</c> class is the controller class for <c>AVAPriceIncrease</c>
/// </summary>
class AVAPriceIncreaseController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmDialogCaption("@NDX:NXAPriceIncreaseCreateJournals");
    this.parmClassName(classStr(AVAPriceIncreaseService));
    this.parmMethodName(methodStr(AVAPriceIncreaseService, runService));
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVAPriceIncreaseController</c> as return value
/// </returns>
public static AVAPriceIncreaseController newFromArgs(Args _args)
{
    AVAPriceIncreaseController controller;

    controller = new AVAPriceIncreaseController();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAPriceIncreaseController      controller;
    AVAPriceIncreaseContract        dataContract;
    SysOperationStartResult         sysOperationStartResult;

    Common                          locCommon;
    AVAPriceIncreasePriceDiscGroup  locAVAPriceIncreasePriceDiscGroup;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVAPriceIncreaseController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();

    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(AVAPriceIncreasePriceDiscGroup))
        {
            locAVAPriceIncreasePriceDiscGroup = locCommon;

            dataContract.parmArgs(_args);
            dataContract.parmAVAPriceIncreaseSet(locAVAPriceIncreasePriceDiscGroup.PriceIncreaseSet);
            dataContract.parmPriceGroupId(locAVAPriceIncreasePriceDiscGroup.GroupId);
            dataContract.parmPriceDiscModule(locAVAPriceIncreasePriceDiscGroup.Module);
            dataContract.parmPriceGroupType(locAVAPriceIncreasePriceDiscGroup.Type);
        }

    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
